using System;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class FeatureFlagsPage:UserControl{DataGridView grid;public FeatureFlagsPage(){Dock=DockStyle.Fill;BackColor=Theme.Background;if(!AppSession.Can("Users.Manage")){Controls.Add(Ui.Label(L.Fa?"فقط مدیر سیستم":"Administrators only",16,true));return;}var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=65,Padding=new Padding(8)};var add=Ui.Button(L.Fa?"افزودن قابلیت":"Add feature");add.Click+=(s,e)=>Add();var toggle=Ui.Button(L.Fa?"فعال/غیرفعال":"Toggle",false);toggle.Click+=(s,e)=>Toggle();top.Controls.AddRange(new Control[]{add,toggle});grid=Ui.Grid();Controls.Add(grid);Controls.Add(top);LoadData();}void LoadData(){grid.DataSource=Database.Query("SELECT Id,FeatureKey,IsEnabled,Description FROM FeatureFlags ORDER BY FeatureKey");}void Add(){string key=InputDialog.ShowValue(this, L.Fa?"قابلیت جدید":"New feature", L.Fa?"کلید قابلیت":"Feature key");if(string.IsNullOrWhiteSpace(key))return;Database.Exec("IF NOT EXISTS(SELECT 1 FROM FeatureFlags WHERE FeatureKey=@k) INSERT FeatureFlags(FeatureKey,IsEnabled,Description) VALUES(@k,1,@d)",new SqlParameter("@k",key.Trim()),new SqlParameter("@d",L.Fa?"قابلیت قابل کنترل":"Configurable feature"));LoadData();}void Toggle(){if(grid.CurrentRow==null)return;int id=Convert.ToInt32(grid.CurrentRow.Cells["Id"].Value);Database.Exec("UPDATE FeatureFlags SET IsEnabled=CASE WHEN IsEnabled=1 THEN 0 ELSE 1 END WHERE Id=@i",new SqlParameter("@i",id));Database.Audit("Toggle","FeatureFlag",id.ToString());LoadData();}}}